#!/usr/bin/env node

// oxlint-disable effect/noNodeBuiltinImport, effect/noTernary, effect/noGlobals -- standalone Node CLI script run from the API generation pipeline.
/**
 * Regenerates the API reference pages under the docs site from the committed
 * core OpenAPI document.
 *
 * The existing pages carry a "generated by Fumadocs" banner, but the command
 * that produced them was never committed — so the tree silently drifted from
 * the contracts. This script reproduces the same layout (one MDX stub per
 * operation, a `meta.json` per group, and a root `meta.json` ordering the
 * groups) so a contract change and its docs can land together.
 *
 * Run `openapi:generate` first; this reads the spec that writes.
 *
 * Usage: node ./scripts/generate-api-reference-docs.mjs [--check]
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const specPath = join(repoRoot, "packages/generated-clients/openapi/core.json");
const referenceRoot = join(
  repoRoot,
  "packages/web-app/src/features/docs/content/docs/api/reference",
);

const checkOnly = process.argv.includes("--check");

/** `listPaywallReleases` → `List Paywall Releases`, matching the existing pages. */
const humanize = (operationName) =>
  operationName
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");

/** `payment_provider_products` → `Payment_provider_products`, as the group pages title them. */
const groupTitle = (groupId) => groupId.charAt(0).toUpperCase() + groupId.slice(1);

const page = (title, method, path) => `---
title: ${title}
full: true
_openapi:
  preload:
    - voidhash-v1
  method: ${method.toUpperCase()}
  webhook: false
  toc: []
  structuredData:
    headings: []
    contents: []
---

{/* This file was generated by Fumadocs. Do not edit this file directly. Any changes should be made by running the generation command again. */}

export default function Layout(props) {
  const { APIPage, OpenAPIPage } = props.components ?? {};
  // "APIPage" is the old name from v10, this allows both for backward compatibility
  const Comp = OpenAPIPage ?? APIPage;
  return (
    <>
      {props.children}
      <Comp document="voidhash-v1" operations={[${JSON.stringify({ path, method })}]} />
    </>
  );
}`;

const spec = JSON.parse(readFileSync(specPath, "utf8"));

/** Groups in first-appearance order, which is the API's own declaration order. */
const groups = new Map();
for (const [path, item] of Object.entries(spec.paths ?? {})) {
  for (const [method, operation] of Object.entries(item)) {
    const operationId = operation?.operationId;
    if (typeof operationId !== "string") continue;
    const [groupId, operationName] = operationId.split(".");
    if (groupId === undefined || operationName === undefined) continue;
    if (!groups.has(groupId)) groups.set(groupId, []);
    groups.get(groupId).push({ method, operationId, operationName, path });
  }
}

/** Every file the spec says should exist, as path → contents. */
const wanted = new Map();
for (const [groupId, operations] of groups) {
  for (const operation of operations) {
    wanted.set(
      join(referenceRoot, groupId, `${operation.operationId}.mdx`),
      page(humanize(operation.operationName), operation.method, operation.path),
    );
  }
  wanted.set(
    join(referenceRoot, groupId, "meta.json"),
    // Key order matches the pages this tree already shipped with, so a
    // regeneration does not churn every group's meta.json.
    `${JSON.stringify(
      { title: groupTitle(groupId), pages: operations.map((operation) => operation.operationId) },
      null,
      2,
    )}\n`,
  );
}
wanted.set(
  join(referenceRoot, "meta.json"),
  `${JSON.stringify({ pages: [...groups.keys()] }, null, 2)}\n`,
);

/** Everything currently on disk, so removed operations get cleaned up. */
const present = new Set();
const walk = (directory) => {
  if (!existsSync(directory)) return;
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const full = join(directory, entry.name);
    if (entry.isDirectory()) walk(full);
    else present.add(full);
  }
};
walk(referenceRoot);

const stale = [...present].filter((file) => !wanted.has(file));
const changed = [...wanted].filter(
  ([file, contents]) => !existsSync(file) || readFileSync(file, "utf8") !== contents,
);

if (checkOnly) {
  if (stale.length === 0 && changed.length === 0) {
    console.log(`API reference docs are up to date (${wanted.size} files).`);
    process.exit(0);
  }
  console.error(
    "API reference docs are out of date. Run: node ./scripts/generate-api-reference-docs.mjs",
  );
  for (const file of changed) console.error(`  changed: ${file[0]}`);
  for (const file of stale) console.error(`  stale:   ${file}`);
  process.exit(1);
}

for (const file of stale) rmSync(file);
for (const [file, contents] of changed) {
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, contents);
}
// Drop group directories the API no longer has.
for (const entry of readdirSync(referenceRoot, { withFileTypes: true })) {
  if (entry.isDirectory() && !groups.has(entry.name)) {
    rmSync(join(referenceRoot, entry.name), { force: true, recursive: true });
  }
}

console.log(
  `Wrote ${changed.length} file(s), removed ${stale.length}; ${groups.size} groups, ${wanted.size - groups.size - 1} operations.`,
);
